-- 0268 設定の定義に、契約者向けの説明 help と、選び肢の言葉 choice_words を持たせる（2026-11-20。書いた人：CL-2。DESIGN_15-2 の923。CL-3 の連絡帳 4-1c の 27・45・CL-2 の連絡帳 4-450）
--
-- ⛔ それまで：説明の文 meaning は、開発の根拠（決めた日付・文書の名前・担当の名前・設定の名前・選び肢の英字の名前）と、契約者への説明が1つの文に混ざっていた。
-- 画面は括弧ごと外す・英字を言葉に置き換える形で出していたので、説明が欠けることがあった（122 のうち 56 に英字）。
-- ⇒ 契約者の画面に出す説明（help）と選び肢の言葉（choice_words＝{値: 言葉}）を、定義の1か所に持つ（画面は出すだけ）。meaning は開発の説明のまま残す。
--    これから足す定義も、help（空でない）と、選ぶ設定なら選び肢すべての言葉が無いと入れられない（データベースが守る）。開発の言葉が入っていないかは試験が見張る。
ALTER TABLE salescall.setting_definitions ADD COLUMN help text, ADD COLUMN choice_words jsonb;
-- 選び肢の言葉が、選び肢のすべてに1つずつあるか（選ぶ設定でなければ言葉を持たない。守りの1か所）
CREATE FUNCTION salescall.choice_words_fit(p_choices text[], p_words jsonb) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$
  SELECT CASE WHEN p_choices IS NULL THEN p_words IS NULL
              ELSE p_words IS NOT NULL AND jsonb_typeof(p_words) = 'object'
                   AND (SELECT coalesce(array_agg(k ORDER BY k), '{}') FROM jsonb_object_keys(p_words) k)
                       = (SELECT coalesce(array_agg(c ORDER BY c), '{}') FROM unnest(p_choices) c)
                   AND NOT EXISTS (SELECT 1 FROM jsonb_each(p_words) e WHERE jsonb_typeof(e.value) <> 'string' OR btrim(e.value #>> '{}') = '') END
$$;
ALTER TABLE salescall.setting_definitions DISABLE TRIGGER USER;
