ALTER TABLE salescall.setting_definitions ENABLE TRIGGER USER;
ALTER TABLE salescall.setting_definitions ALTER COLUMN help SET NOT NULL,
  ADD CONSTRAINT setting_definitions_help CHECK (btrim(help) <> ''),
  ADD CONSTRAINT setting_definitions_choice_words CHECK (salescall.choice_words_fit(choices, choice_words));
